import com.github.benmanes.caffeine.cache.Cache;
import com.github.benmanes.caffeine.cache.Caffeine;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

public class HotKeyHandler<K, V> {
    private final Cache<K, V> localCache;
    private final ConcurrentMap<K, CompletableFuture<V>> inFlightRequests = new ConcurrentHashMap<>();

    public HotKeyHandler() {
        this.localCache = Caffeine.newBuilder()
            .maximumSize(10_000)
            .expireAfterWrite(5, TimeUnit.SECONDS)
            .recordStats()
            .build();
    }

    public CompletableFuture<V> getAsync(K key, Supplier<V> loader) {
        V cachedValue = localCache.getIfPresent(key);
        if (cachedValue != null) {
            return CompletableFuture.completedFuture(cachedValue);
        }

        return inFlightRequests.computeIfAbsent(key, k -> 
            CompletableFuture.supplyAsync(loader)
                .whenComplete((val, ex) -> {
                    if (ex == null && val != null) {
                        localCache.put(k, val);
                    }
                    inFlightRequests.remove(k);
                })
        );
    }
}
